import Chat from './components/Chat'
import './App.css';
import { useState, useEffect } from 'react';

function App() {
  const [darkMode, setDarkMode] = useState(false);
  useEffect(() => {
    document.body.classList.toggle('dark-mode', darkMode);
  }, [darkMode]);
  return (
    <div className="App">
      <Chat />
    </div>
  );
}

export default App;
